package com.networkmonitorpro.data.repository; import android.content.*; import androidx.lifecycle.*; import com.networkmonitorpro.data.db.AppDatabase; import com.networkmonitorpro.data.entity.NotificationHistory; import java.util.*; public class NotificationRepository{ private final AppDatabase db; public NotificationRepository(Context c){db=AppDatabase.get(c);} public LiveData<List<NotificationHistory>> all(){return db.notificationDao().all();} public LiveData<List<NotificationHistory>> search(String q){return db.notificationDao().search(q);} public void add(String type,String title,String msg){AppExecutors.IO.execute(()->db.notificationDao().insert(new NotificationHistory(type,title,msg,System.currentTimeMillis())));} public void clear(){AppExecutors.IO.execute(()->db.notificationDao().clear());} }
